export const BRUTO: Bruto[] = [
  [1, "", 1, "pt", "Compreensão de texto", [0, 1], "O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.", "E", "O texto explica por que o gênero policial faz sucesso, mas não diz que ele é o preferido do público. A preferência foi inventada pelo item.", ""],
  [2, "", 1, "pt", "Compreensão de texto", [0, 1], "Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.", "E", "O texto não liga as adaptações à expectativa de repetir o sucesso de vendas. A explicação que ele dá é o estilo narrativo, com o qual o público se identifica.", ""],
  [3, "", 1, "pt", "Compreensão de texto", [0, 1], "A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.", "C", "Segundo Gerbase, quando nos identificamos com um personagem, aprendemos a agir socialmente. Logo, as histórias podem nortear a conduta de leitores e espectadores.", ""],
  [4, "", 1, "pt", "Significação das palavras", [0, 1], "O termo \"crescente\" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.", "E", "“Crescente” é o que está aumentando; “considerável” é o que é grande. A troca muda o sentido: a quantidade pode ser grande sem estar crescendo.", ""],
  [5, "", 1, "pt", "Orações subordinadas", [0, 1], "No segundo período do segundo parágrafo, a oração \"que as histórias têm começo, meio e fim\" classifica-se sintaticamente como subordinada adjetiva restritiva.", "E", "A oração “que as histórias têm começo, meio e fim” completa o verbo “explica” (o autor explica isso): é subordinada substantiva objetiva direta, e não adjetiva.", ""],
  [6, "", 1, "pt", "Pontuação", [0, 1], "A supressão da vírgula empregada após \"personagem\" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.", "C", "A oração “quando nos identificamos com determinado personagem” está intercalada: abre com a vírgula depois de “Gerbase” e fecha com a vírgula depois de “personagem”. Tirar só a segunda deixa a intercalação sem fechamento.", ""],
  [7, "", 1, "pt", "Conectivos", [0, 1], "No segundo parágrafo, o intercambiamento das expressões \"Logo\" (terceiro período) e \"Além disso\" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.", "E", "“Logo” indica conclusão e “Além disso” indica acréscimo. Trocar um pelo outro faria uma ideia nova parecer conclusão e uma conclusão parecer acréscimo, e a coerência se perde.", ""],
  [8, "", 1, "pt", "Coesão (pronomes)", [0, 1], "O pronome presente no termo \"nela\" (último parágrafo) tem como referente \"a narrativa policial\".", "C", "“Nela” é “em + ela”, e o pronome retoma “a narrativa policial”: é nela que as pessoas buscam sanar suas preocupações.", ""],
  [9, "", 1, "pt", "Redação oficial", [2], "Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.", "C", "Pelo Manual de Redação da Presidência, a impessoalidade decorre de a comunicação ser feita sempre em nome do serviço público e no interesse geral dos cidadãos.", ""],
  [10, "", 1, "pt", "Redação oficial", [2], "Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.", "C", "O Manual de Redação da Presidência trata dos pronomes de tratamento em três usos: no endereçamento, no vocativo e no corpo do texto.", ""],
  [11, "", 1, "adm", "Atributos do ato administrativo", [3], "A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.", "E", "A primeira parte está certa: a presunção de veracidade se refere aos fatos. Mas o atributo de impor o ato a terceiros sem a concordância deles é a imperatividade. A autoexecutoriedade é executar o ato sem precisar do Judiciário.", ""],
  [12, "", 1, "adm", "Responsabilidade civil do Estado", [3], "A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.", "E", "A ação vai contra a pessoa jurídica a que o agente está ligado. Pelo Tema 940 do STF (2019), pode ser o Estado ou a pessoa jurídica de direito privado prestadora de serviço público. Por isso “somente contra o Estado” está errado. O servidor não é réu direto: responde depois, em ação de regresso.", "O gabarito preliminar era Certo. A banca mudou para Errado depois dos recursos, com base no Tema 940 do STF."],
  [13, "", 1, "adm", "Administração indireta", [3], "As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.", "C", "As duas exploram atividade econômica (ou prestam serviço público). A diferença está na forma: a sociedade de economia mista é sempre sociedade anônima, e a empresa pública pode ter qualquer forma. Está também no capital: na empresa pública ele é todo público, e na mista é misto, com controle público.", ""],
  [14, "", 1, "adm", "Lei 8.112/1990 (penalidades)", [3], "O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.", "E", "O registro da suspensão é cancelado após 5 anos de efetivo exercício sem nova infração, e não 2 (o de advertência é após 3). E o cancelamento não produz efeitos retroativos (art. 131, parágrafo único).", ""],
  [15, "", 1, "adm", "Licitações (Lei 14.133/2021)", [3], "É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.", "E", "Esse caso é de licitação dispensável (art. 75, VI), e não de inexigibilidade. A inexigibilidade é quando a competição é inviável.", ""],
  [16, "", 1, "adm", "Princípios da administração", [3], "O princípio da razoabilidade é considerado um princípio implícito da administração pública e se baseia naquilo que se situa dentro de limites aceitáveis.", "C", "A razoabilidade não está escrita no art. 37 da CF: é um princípio implícito. Ela exige que a atuação fique dentro de limites aceitáveis, de bom senso.", ""],
  [17, "", 1, "con", "Direitos fundamentais (sigilo)", [4], "O sigilo da correspondência e das comunicações telefônicas pode ser afastado por determinação judicial, quando isso for necessário à apuração de infrações penais ou administrativas, conforme dispuser a lei.", "E", "Pelo art. 5.º, XII, da CF, só as comunicações telefônicas podem ser interceptadas, por ordem judicial, e apenas para investigação criminal ou instrução processual penal. Não vale para infração administrativa.", ""],
  [18, "", 1, "con", "Forma e sistema de governo", [4], "A forma de governo diz respeito à relação entre os Poderes Executivo e Legislativo, ao passo que o sistema de governo refere-se à origem e à titularidade do poder político.", "E", "O item inverteu os conceitos. A forma de governo (república ou monarquia) diz respeito à origem e à titularidade do poder. O sistema de governo (presidencialismo ou parlamentarismo) diz respeito à relação entre o Executivo e o Legislativo.", ""],
  [19, "", 1, "con", "Segurança pública (PF)", [5], "Cabe à Polícia Federal exercer, com exclusividade, as funções de polícia judiciária da União, dos estados e do Distrito Federal.", "E", "A PF exerce com exclusividade a polícia judiciária da União (CF, art. 144, § 1.º, IV). A dos estados e do DF cabe às polícias civis (§ 4.º).", ""],
  [20, "", 1, "con", "Meio ambiente", [5], "Além das pessoas físicas, as pessoas jurídicas também podem ser responsabilizadas penalmente pela prática de crimes ambientais.", "C", "A CF prevê sanções penais também para pessoas jurídicas que causem dano ambiental (art. 225, § 3.º), e a Lei 9.605/1998 regula isso (art. 3.º).", ""],
  [21, "", 1, "con", "Indígenas", [5], "A pesquisa e a lavra de minerais em terras indígenas só podem ser efetivadas mediante autorização do Congresso Nacional.", "C", "Pela CF, a pesquisa e a lavra de riquezas minerais em terras indígenas só podem ocorrer com autorização do Congresso Nacional, ouvidas as comunidades afetadas (art. 231, § 3.º).", ""],
  [22, "", 1, "con", "Segurança pública (PRF)", [5], "O patrulhamento ostensivo das ferrovias federais compete à Polícia Rodoviária Federal.", "E", "Pelo art. 144 da CF, a PRF patrulha as rodovias federais (§ 2.º). As ferrovias federais ficam com a Polícia Ferroviária Federal (§ 3.º).", "A PEC 18/2025 (PEC da Segurança Pública), aprovada pelo Senado em 3/11/2026 e ainda à espera de promulgação, estende a atuação da PRF às ferrovias e hidrovias federais. Se for promulgada, este item terá de ser revisto."],
  [23, "", 1, "penal", "Prevaricação", [6], "O crime de prevaricação exige, além da conduta típica de retardar, deixar de praticar ou praticar indevidamente ato de ofício, o dolo específico de satisfazer interesse ou sentimento pessoal, não sendo suficiente a constatação de mera negligência ou descompromisso funcional.", "C", "Para o STJ, a prevaricação (CP, art. 319) exige o dolo específico de satisfazer interesse ou sentimento pessoal. Negligência ou desleixo no serviço não bastam.", ""],
  [24, "", 1, "penal", "Roubo (arma branca)", [6], "O uso de um cabo de vassoura contra a vítima durante a prática de roubo pode justificar a aplicação da causa de aumento de pena prevista no art. 157, § 2.º, VII, do CP, desde que comprovada sua potencialidade lesiva, ainda que não haja perícia ou apreensão do objeto.", "C", "O aumento do art. 157, § 2.º, VII (violência ou grave ameaça com arma branca) alcança objetos com potencial de ferir, como um cabo de vassoura usado contra a vítima. Para o STJ, não é preciso apreender o objeto nem fazer perícia se o potencial lesivo for provado de outro modo.", ""],
  [25, "", 1, "penal", "Furto qualificado (escalada)", [6], "Considere que um casal tenha sido preso em flagrante enquanto furtava cabos de energia elétrica em via pública: a mulher encontrava-se ao lado do poste de energia com uma mochila onde estavam armazenados diversos metros de fios já cortados e perto dela havia um facão utilizado para o corte; o homem se encontrava no alto do poste, com o facão em mãos, em plena retirada de novos cabos. Nessa situação, a ausência de laudo pericial sobre o local e os meios utilizados impede, em relação à mulher, a configuração da qualificadora da escalada no crime de furto, ainda que policiais tenham presenciado diretamente a prática delitiva e narrado detalhadamente os fatos.", "E", "Para o STJ, a falta de laudo não impede reconhecer a escalada quando outras provas a demonstram com clareza, como o flagrante presenciado e narrado em detalhe pelos policiais. E, como é circunstância objetiva conhecida pela coautora, ela também a alcança (CP, art. 30).", ""],
  [26, "", 1, "proc", "Inquérito policial (instauração)", [7], "O inquérito policial poderá ser iniciado mediante requerimento do ofendido, mesmo nos crimes de ação pública incondicionada.", "C", "Nos crimes de ação pública incondicionada, o inquérito começa de ofício, por requisição ou a requerimento do ofendido ou de quem tiver qualidade para representá-lo (CPP, art. 5.º, II).", ""],
  [27, "", 1, "proc", "Inquérito policial (instauração)", [7], "A autoridade policial deve instaurar inquérito policial sempre que qualquer pessoa do povo comunicar, verbalmente ou por escrito, a ocorrência de uma infração penal, independentemente da natureza da ação penal ou da verificação da procedência das informações.", "E", "Qualquer pessoa pode comunicar a infração, mas só nos crimes de ação pública. E a autoridade instaura o inquérito depois de verificar se as informações procedem (CPP, art. 5.º, § 3.º). O item erra nos dois pontos.", ""],
  [28, "", 1, "penal", "Lei penal no espaço", [8, 9], "Como o crime ocorreu fora do território brasileiro, em alto-mar, e não envolveu embarcação pública, a lei penal brasileira não pode ser aplicada ao caso.", "E", "Embarcações brasileiras privadas em alto-mar são consideradas extensão do território nacional (CP, art. 5.º, § 1.º). A lei penal brasileira se aplica por territorialidade.", ""],
  [29, "", 1, "dh", "Regras de Mandela", [10], "Na admissão de indivíduos em estabelecimentos prisionais, deverá ser adicionado, no sistema de registro do recluso, inventário dos seus bens pessoais.", "C", "Pela regra 7 das Regras de Mandela, o registro do preso na admissão deve trazer, entre outros dados, um inventário dos seus bens pessoais.", ""],
  [30, "", 1, "dh", "Regras de Mandela", [10], "As Regras de Mandela contemplam a possibilidade de se impor ao recluso a realização de trabalho no estabelecimento prisional em cumprimento de qualquer medida disciplinar.", "E", "As Regras de Mandela não tratam o trabalho como castigo: o trabalho prisional não pode ter natureza penosa (regra 97). Impor trabalho como cumprimento de qualquer medida disciplinar contraria essa lógica.", ""],
  [31, "", 1, "dh", "Regras de Mandela", [10], "A separação de categorias de pessoas presas deve orientar-se por critérios de gênero, idade e natureza dos delitos, não havendo regra que determine a separação dos presos em razão da natureza da detenção, isto é, se preventiva ou se oriunda de condenação definitiva.", "E", "A regra 11 manda separar também os presos preventivos dos condenados, além de homens e mulheres, jovens e adultos, presos civis e criminais. Existe, portanto, regra sobre a natureza da detenção.", ""],
  [32, "", 1, "dh", "Garantias judiciais", [10], "Qualquer pessoa declarada culpada por um delito terá o direito de recorrer a uma instância superior para rever a sentença condenatória que lhe tenha sido imposta e a pena que lhe tenha sido aplicada.", "C", "O Pacto Internacional sobre Direitos Civis e Políticos (art. 14, 5) garante a quem for declarado culpado o direito de recorrer a uma instância superior, que reexamine a condenação e a pena.", ""],
  [33, "", 1, "dh", "Convenção contra a Tortura", [11], "Os Estados-partes da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes devem incluir os atos de tortura como crimes extraditáveis em todos os tratados de extradição que vierem a concluir entre si.", "C", "Pela Convenção (art. 8.º), a tortura é considerada crime extraditável nos tratados de extradição já existentes entre os Estados-partes, e eles se comprometem a incluí-la em todos os tratados que vierem a concluir.", ""],
  [34, "", 1, "dh", "Estatuto dos Refugiados", [11], "A Convenção Relativa ao Estatuto dos Refugiados veda aos Estados contratantes, em qualquer circunstância, a expulsão de refugiados.", "E", "A Convenção de 1951 permite expulsar refugiado que esteja regularmente no território por motivo de segurança nacional ou de ordem pública (art. 32). A vedação não vale “em qualquer circunstância”.", ""],
  [35, "", 1, "especial", "ECA (ato infracional)", [12], "O pedido do Ministério Público para aplicação de medida socioeducativa deverá ser julgado improcedente pela autoridade judiciária nas seguintes hipóteses: comprovação da inexistência do fato; ausência de prova da existência do fato; não caracterização do fato como ato infracional; e falta de prova da participação do adolescente no ato infracional.", "C", "O ECA (art. 189) lista exatamente essas quatro hipóteses em que o juiz não aplica medida: inexistência do fato provada, falta de prova do fato, fato que não é ato infracional e falta de prova da participação do adolescente.", ""],
  [36, "", 1, "especial", "Estatuto da Segurança Privada", [12], "No âmbito da segurança privada, compete à Polícia Federal renovar, a cada dois anos, a autorização de funcionamento das empresas de monitoramento de sistemas eletrônicos de segurança que atuam, simultaneamente, em mais de um estado da Federação.", "E", "Pela Lei 14.967/2024 (art. 40, II), a PF renova a autorização das empresas de serviços de segurança a cada 2 anos, mas a das empresas de monitoramento de sistemas eletrônicos de segurança a cada 5 anos.", ""],
  [38, "", 1, "especial", "Lei de Drogas (bens apreendidos)", [12], "A apreensão dos meios de transporte e dos maquinários, utensílios, instrumentos e objetos de qualquer natureza utilizados para a prática, habitual ou não, do tráfico ilícito de drogas deve ser imediatamente comunicada pela autoridade de polícia judiciária responsável pela investigação ao juízo competente, que, no prazo de trinta dias, contado dessa comunicação, deve determinar a alienação dos bens apreendidos, excetuadas as armas.", "C", "Pela Lei 11.343/2006 (art. 61), a apreensão é comunicada de imediato ao juízo, que em 30 dias determina a alienação dos bens, exceto as armas, que seguem a legislação própria.", ""],
  [39, "", 1, "especial", "Lei de Tortura", [12], "O condenado por crime de tortura, bem como aquele que se houver omitido em face das condutas que o caracterizam quando tinha o dever de evitá-las ou apurá-las, iniciará o cumprimento da pena em regime fechado.", "E", "O regime inicial fechado vale para o condenado por tortura, salvo a hipótese do § 2.º do art. 1.º da Lei 9.455/1997: a de quem se omite quando devia evitar ou apurar a tortura. O item incluiu justamente a exceção.", ""],
  [40, "", 1, "especial", "Carteira de identidade", [13], "A carteira de identidade fará prova de todos os dados nela incluídos, dispensando a apresentação dos documentos que lhe deram origem ou que nela tenham sido mencionados.", "C", "Pela Lei 7.116/1983, a carteira de identidade faz prova de todos os dados nela incluídos e dispensa a apresentação dos documentos que lhe deram origem ou que nela forem mencionados.", ""],
  [41, "", 1, "especial", "Identificação do cidadão", [13], "No âmbito do Serviço de Identificação do Cidadão, compete à Polícia Federal definir especificações técnicas de documentos de segurança vinculados à identificação de pessoas naturais e regulamentar o procedimento a ser adotado em caso de divergência na verificação dos dados da pessoa natural.", "E", "Pelo Decreto 11.797/2023, quem edita essas normas é a Câmara-Executiva Federal de Identificação do Cidadão (Cefic) (art. 10, V). A PF apenas propõe à Cefic as especificações e a regulamentação do procedimento (art. 22, I).", ""],
  [42, "", 1, "especial", "Atribuições da PF (Lei 10.446/2002)", [13], "Quando houver repercussão interestadual ou internacional que exija repressão uniforme, poderá o Departamento de Polícia Federal do Ministério da Justiça, sem prejuízo da responsabilidade dos órgãos de segurança pública arrolados na Constituição Federal de 1988, proceder à investigação de quaisquer crimes praticados por meio da rede mundial de computadores que difundam conteúdo misógino, definido como aquele que propaga ódio ou aversão às mulheres.", "C", "A Lei 10.446/2002 (art. 1.º, VII) permite à PF investigar, quando houver repercussão interestadual ou internacional que exija repressão uniforme, crimes praticados pela internet que difundam conteúdo misógino, ou seja, que propaguem ódio ou aversão às mulheres.", ""],
  [43, "", 1, "especial", "Estatuto do Desarmamento", [13], "Pratica crime o proprietário de empresa de segurança e transporte de valores que, nas primeiras 24 horas depois de sofrer perda, furto, roubo ou outra forma de extravio de arma de fogo, acessório ou munição que estejam sob sua guarda, deixa de registrar ocorrência policial e de comunicar o fato à Polícia Federal.", "C", "Pelo art. 13, parágrafo único, da Lei 10.826/2003, o dono ou diretor de empresa de segurança e transporte de valores que não registra ocorrência e não comunica a PF em 24 horas após perda, furto, roubo ou extravio de arma, acessório ou munição comete crime.", ""],
  [44, "", 1, "especial", "Crimes ambientais", [13], "Nas infrações penais derivadas de condutas e atividades lesivas ao meio ambiente, a ação penal é pública incondicionada.", "C", "Nas infrações penais da Lei 9.605/1998, a ação penal é pública incondicionada (art. 26).", ""],
  [45, "", 1, "estat", "Distribuição normal", [14], "A mediana de S é igual a (X₂ + X₃)/2.", "E", "S = X₁ + X₂ + X₃ + X₄ é uma variável aleatória com distribuição normal de média 4M. Como a normal é simétrica, a mediana de S é 4M, um número fixo, e não (X₂ + X₃)/2.", ""],
  [46, "", 1, "estat", "Distribuição normal", [14], "S segue uma distribuição binomial com parâmetro n = 4.", "E", "A soma de variáveis normais independentes também é normal (média 4M e variância 4V). A distribuição binomial é de contagem de sucessos, o que não é o caso.", ""],
  [47, "", 1, "estat", "Distribuição normal", [14], "A probabilidade de S = 4 × M é zero.", "C", "S é uma variável contínua. Em variável contínua, a probabilidade de assumir um valor exato, como 4M, é sempre zero.", ""],
  [48, "", 1, "estat", "Variância", [14], "O desvio padrão da razão S/√V é igual a 2.", "C", "A variância da soma de 4 variáveis independentes é 4V, então o desvio padrão de S é 2√V. Dividindo por √V, o desvio padrão de S/√V fica 2.", ""],
  [49, "", 1, "estat", "Correlação e regressão", [15, 16], "O coeficiente de correlação linear de Pearson entre as variáveis VL e VP foi igual a 1,1.", "E", "1,1 é o coeficiente angular da reta de regressão, não a correlação. O coeficiente de Pearson fica sempre entre –1 e 1, então nunca poderia ser 1,1.", ""],
  [50, "", 1, "estat", "Intervalo de confiança", [15, 16], "O intervalo de 95% confiança para a diferença entre as médias populacionais dos valores licitados e dos valores efetivamente pagos foi R$ 5 mil ± R$ 0,5 mil.", "E", "O erro padrão da média é 3 ÷ √36 = 0,5 mil. O intervalo de 95% soma e subtrai cerca de 2 erros padrão (1,96 ou t ≈ 2,03): 5 ± 1 mil, aproximadamente. O ± 0,5 mil corresponde a apenas 1 erro padrão.", ""],
  [51, "", 1, "estat", "Correlação e regressão", [15, 16], "O desvio padrão da variável VL foi superior ao desvio padrão da variável VP.", "C", "Na regressão, o coeficiente angular é b = r × (DP de VL ÷ DP de VP). Como b = 1,1 e r não passa de 1, a razão entre os desvios padrão é de pelo menos 1,1: o de VL é maior.", ""],
  [53, "", 1, "rlm", "Tabela-verdade", [17], "Considere que, na tabela-verdade a seguir, P, Q e R sejam proposições, → denote o condicional “se... então...”, “∨”, o conectivo “ou”, e ~R, a negação da proposição R. Com base nessas considerações, conclui-se que, ao preencher corretamente a última coluna da tabela-verdade, ocorrerão 4 valores V (verdade) e 4 valores F (falso).\n\nP  Q  R  |  P ∨ Q → ~R\nV  V  V  |\nV  V  F  |\nV  F  V  |\nV  F  F  |\nF  V  V  |\nF  V  F  |\nF  F  V  |\nF  F  F  |", "E", "A coluna é (P ∨ Q) → ~R. Ela só é falsa quando P ∨ Q é V e R é V: nas linhas VVV, VFV e FVV. São 3 valores F e 5 valores V, e não 4 e 4.", ""],
  [54, "", 1, "rlm", "Lógica de argumentação", [17], "Considere que um crime foi cometido e três suspeitos desse crime, X, Y e Z, foram intimados e conduzidos a um interrogatório. Nessa ocasião, sobre o crime,\n• X afirmou: “nem Y nem Z são culpados”;\n• Z afirmou: “os culpados foram Y e X”; e\n• Y afirmou: “o culpado foi Z ou X”.\nNessa situação, sabendo-se que todos os suspeitos mentiram, é correto concluir que o culpado do crime é X.", "E", "Todos mentiram. Pela fala de Y, nem Z nem X é culpado. Pela fala de X, Y ou Z é culpado. Como Z é inocente, o culpado é Y, e não X.", ""],
  [55, "", 1, "rlm", "Lógica de argumentação", [17], "Considere que as seguintes proposições sejam verdadeiras. P: “Se Paulo é parente da vítima, então ele é inocente e estava no exterior no dia do crime”. Q: “Se Paulo tem o mesmo sobrenome da vítima ou tem o mesmo tipo sanguíneo, então ele é parente da vítima”. Com base nessas proposições, é correto afirmar que, se Paulo não estava no exterior no dia do crime, então ele não tem o mesmo tipo sanguíneo da vítima.", "C", "Se Paulo não estava no exterior, a conclusão de P é falsa, então ele não é parente (modus tollens). Pela mesma regra em Q, ele não tem o mesmo sobrenome nem o mesmo tipo sanguíneo.", ""],
  [56, "", 1, "rlm", "Lógica de argumentação", [17], "Suponha que a sentença “Se Aldo ou Bruno é filho de Carlos, então Daniel é pai de Elza e de Fernanda” seja verdadeira. Nesse caso, se Elza não for filha de Daniel, então Carlos não é pai de Aldo nem de Bruno.", "C", "Se Elza não é filha de Daniel, a conclusão “Daniel é pai de Elza e de Fernanda” é falsa. Então a condição também é falsa: nem Aldo nem Bruno são filhos de Carlos (modus tollens).", ""],
  [57, "", 1, "rlm", "Negação de proposições", [18, 19], "A negação da sentença “todo condutor abordado na fiscalização era brasileiro ou estrangeiro” é a seguinte sentença: “nenhum condutor abordado na fiscalização era brasileiro ou estrangeiro”.", "E", "A negação de “todo condutor era brasileiro ou estrangeiro” é “algum condutor não era brasileiro nem estrangeiro”. Trocar “todo” por “nenhum” não nega a frase.", ""],
  [58, "", 1, "rlm", "Probabilidade", [18, 19], "Se duas placas forem aleatoriamente selecionadas ao final do dia entre as 1.000 placas registradas, será superior a 0,3 a probabilidade de uma delas pertencer a um veículo/condutor/carga em situação irregular e a outra, a um veículo/condutor/carga em situação regular.", "C", "A probabilidade é 2 × (200/1.000) × (800/999) ≈ 0,32, maior que 0,3. O fator 2 vem das duas ordens possíveis (irregular e regular, ou regular e irregular).", ""],
  [59, "", 1, "rlm", "Princípio da casa dos pombos", [18, 19], "Considere que as placas de todos os veículos sejam constituídas por uma sequência de 4 letras justaposta a uma sequência de 3 dígitos numéricos entre 0 e 9, admitindo-se repetições. Considere, ainda, que a soma dos dígitos numéricos da placa de cada um dos 1.000 veículos fiscalizados seja sempre superior ou igual a 26. Nessa situação, pelo menos 250 placas têm os mesmos dígitos numéricos, nas mesmas posições.", "C", "Com 3 dígitos de 0 a 9, a soma só chega a 26 ou 27 com 999, 998, 989 e 899: 4 sequências possíveis. Distribuindo 1.000 placas em 4 sequências, pelo menos 250 caem na mesma.", ""],
  [60, "", 1, "rlm", "Conjuntos", [18, 19], "Considere que, entre os veículos em situação irregular,\n• 120 apresentavam problemas na documentação do veículo;\n• 85, na documentação do condutor; e\n• 40, na documentação da carga transportada.\nAlém disso, os veículos com problemas na documentação da carga não apresentavam problemas na documentação do veículo nem na documentação do condutor. Nessa situação, é inferior a 40 a quantidade de veículos que apresentavam, simultaneamente, irregularidades na documentação do veículo e do seu condutor.", "E", "Os 40 da carga não têm outro problema, então 200 – 40 = 160 veículos têm problema no veículo ou no condutor. A interseção é 120 + 85 – 160 = 45, que não é inferior a 40.", ""],
  [61, "", 2, "info", "Internet (acesso remoto e aplicativos)", [20], "O Microsoft Remote Desktop e o TeamViewer permitem acesso remoto a computadores, o que possibilita a transferência de arquivos, e os ambientes Microsoft Office e LibreOffice oferecem ferramentas para criação de textos, planilhas e apresentações, garantindo compatibilidade com diversos formatos.", "C", "Microsoft Remote Desktop e TeamViewer são ferramentas de acesso remoto que também permitem transferir arquivos. Microsoft Office e LibreOffice trazem editor de texto, planilha e apresentação, e abrem e salvam em vários formatos.", ""],
  [63, "", 2, "info", "Comandos de rede", [20], "Em distribuições Linux, o comando ipconfig é utilizado para exibir informações de configuração de rede, como endereço IP e máscara de sub-rede; no Windows, o comando ifconfig desempenha a mesma função, permitindo a visualização e configuração de interfaces de rede.", "E", "Está invertido: no Windows, o comando é ipconfig; no Linux, ifconfig (hoje também o comando ip).", ""],
  [64, "", 2, "info", "Segurança (firewall e antivírus)", [21], "Firewalls são ferramentas de segurança que monitoram e controlam o tráfego de dados entre redes, podendo bloquear acessos não autorizados, ao passo que os antivírus são projetados para detectar, remover e prevenir a ação de vírus e outras pragas virtuais.", "C", "O firewall filtra o tráfego entre redes conforme regras e pode bloquear acessos não autorizados. O antivírus detecta, remove e previne vírus e outros malwares.", ""],
  [65, "", 2, "info", "Redes (IPv4 e IPv6)", [21], "No protocolo IPv6, cada endereço tem 256 bits, que são divididos em duas partes (a primeira define a rede e a segunda identifica o host); esse protocolo elimina o uso de máscaras de sub-rede, substituindo-as por prefixos de rede fixos; por sua vez, o IPv4 utiliza endereços de 32 bits e máscaras de sub-rede variáveis para definir a separação entre rede e host.", "E", "O endereço IPv6 tem 128 bits, e não 256. E o IPv6 não usa prefixos fixos: o tamanho do prefixo é indicado na notação /n (como /64), de forma parecida com o CIDR do IPv4.", ""],
  [66, "", 2, "info", "Teoria geral de sistemas", [22], "Na arquitetura de sistemas, o frontend é a interface visível e interativa com o usuário, enquanto o backend realiza o processamento de dados e a lógica de negócios; essa separação reflete os princípios da teoria geral de sistemas, segundo a qual a organização de sistemas em partes interdependentes facilita sua compreensão e manutenção.", "C", "O frontend é a camada que o usuário vê e com a qual interage; o backend processa os dados e as regras de negócio. Dividir o sistema em partes interdependentes que funcionam como um todo é uma ideia da teoria geral de sistemas.", ""],
  [67, "", 2, "info", "Computação em nuvem", [22], "A computação em nuvem permite que os usuários acessem recursos computacionais sob demanda, como armazenamento e processamento, sem a necessidade de conexão com a Internet, pois os dados e serviços são armazenados localmente nos dispositivos dos usuários.", "E", "A computação em nuvem depende de conexão com a rede, em geral a Internet: os dados e serviços ficam nos servidores do provedor, não no dispositivo do usuário.", ""],
  [68, "", 2, "info", "Sistemas de informação (requisitos)", [22], "Na análise de requisitos de um sistema de informação, a etapa de especificação pode ser desconsiderada e substituída diretamente pelos ambientes de testes, homologação e produção, desde que os requisitos tenham sido bem definidos e documentados.", "E", "A especificação é a etapa que documenta o que o sistema deve fazer e não pode ser pulada. Os ambientes de teste, homologação e produção vêm depois, para verificar e entregar o que foi especificado.", ""],
  [70, "", 2, "info", "Mineração de dados e Big Data", [23], "A mineração de dados é uma técnica em que se utilizam exclusivamente algoritmos de aprendizado supervisionado para a identificação de padrões em grandes volumes de dados; no contexto de Big Data, a premissa principal é a utilização de bancos de dados relacionais tradicionais, que são suficientes para o enfrentamento dos desafios de volume, variedade e velocidade característicos desse ambiente.", "E", "A mineração de dados usa técnicas supervisionadas (como classificação) e não supervisionadas (como agrupamento e regras de associação). E o Big Data se apoia em sistemas distribuídos e bancos NoSQL, porque os bancos relacionais tradicionais não dão conta do volume, da variedade e da velocidade dos dados.", ""],
  [71, "", 2, "info", "Banco de dados (tipos de dados)", [23], "No contexto de banco de dados, dados estruturados são aqueles que não possuem um formato fixo e são armazenados em sistemas como bancos NoSQL, ao passo que dados não estruturados possuem um formato rígido e são armazenados em tabelas relacionais.", "E", "Está invertido: dados estruturados têm formato fixo e ficam em tabelas relacionais; dados não estruturados (textos, imagens, vídeos) não têm formato fixo e costumam ficar em repositórios como os bancos NoSQL.", ""],
  [72, "", 2, "info", "Teoria da informação", [23], "Na teoria da informação, dados representam fatos brutos que, quando organizados e interpretados, se transformam em informação, e a segurança da informação busca protegê-los contra acessos não autorizados, garantindo sua confidencialidade, integridade e disponibilidade.", "C", "Dados são fatos brutos; organizados e interpretados, viram informação. A segurança da informação protege esses dados com base na confidencialidade, na integridade e na disponibilidade.", ""],
  [73, "", 2, "info", "Biometria (FPIR e FNIR)", [24], "Em sistemas biométricos de alta segurança, o controle do FNIR é mais relevante que o do FPIR, pois rejeitar um usuário legítimo acarreta maior risco que aceitar um impostor.", "E", "Em alta segurança, o mais grave é aceitar um impostor, o que é medido pelo FPIR (taxa de falsos positivos na identificação). Rejeitar um usuário legítimo (FNIR) incomoda, mas oferece menos risco. O item inverte.", ""],
  [74, "", 2, "info", "Biometria (FPIR e FNIR)", [24], "O indicador FPIR é diretamente influenciado por um limiar de decisão mal ajustado, o que pode comprometer a segurança de sistemas biométricos ao se aceitarem usuários não autorizados.", "C", "O FPIR depende do limiar de decisão: com o limiar mal ajustado, o sistema passa a aceitar como iguais biometrias diferentes, e usuários não autorizados entram.", ""],
  [75, "", 2, "info", "Python", [24], "Em Python, a função lambda permite a criação de funções anônimas, que podem ser usadas como argumentos em funções de ordem superior, o que facilita a programação funcional.", "C", "Em Python, lambda cria funções anônimas de uma só expressão, muito usadas como argumento de funções de ordem superior, como map, filter e sorted.", ""],
  [76, "", 2, "info", "Transmissão de dados", [24], "No modo de transmissão full-duplex, para que os dados sejam transmitidos simultaneamente em ambos os sentidos, os dispositivos devem estar sincronizados no mesmo clock lógico de rede.", "E", "No full-duplex, os dois lados transmitem ao mesmo tempo, em canais ou faixas separados. Não se exige que os dispositivos estejam no mesmo clock lógico de rede.", ""],
  [77, "", 2, "info", "Modelo OSI", [24], "A camada de sessão do modelo OSI é a principal responsável pela fragmentação e reconstrução de pacotes IP entre sistemas finais na rede.", "E", "Fragmentar e remontar pacotes IP é tarefa da camada de rede (camada 3). A camada de sessão (camada 5) abre, mantém e encerra as sessões entre as aplicações.", ""],
  [78, "", 2, "info", "Python", [24], "Em Python, listas são estruturas de dados imutáveis, o que as torna ideais para serem usadas como chaves de dicionários (dict).", "E", "Em Python, listas são mutáveis e, por isso, não podem ser chaves de dicionário. As tuplas, que são imutáveis, podem.", ""],
  [79, "", 2, "info", "Computação em nuvem", [25], "Em serviços de nuvem, a utilização de plataforma como serviço (PaaS) é mais recomendada para empresas que desejem controlar totalmente o hardware e o sistema operacional utilizados.", "E", "No PaaS, o provedor administra o hardware e o sistema operacional, e o cliente cuida só das aplicações. Quem quer controlar o sistema operacional escolhe o IaaS, e nenhum modelo de nuvem dá controle total do hardware.", ""],
  [80, "", 2, "info", "Machine learning", [25], "Em machine learning supervisionado, o algoritmo aprende, a partir de um conjunto de dados rotulados, a identificar padrões e realizar previsões em novos dados.", "C", "No aprendizado supervisionado, o algoritmo é treinado com dados rotulados (entradas com a resposta certa) e aprende padrões para prever o resultado de dados novos.", ""],
  [81, "", 2, "info", "Linux (permissões)", [25], "No ambiente Linux, a execução do comando apresentado a seguir atribuirá permissões de leitura, escrita e execução para o proprietário do arquivo policial.pdf, e atribuirá permissões de leitura e execução para grupo e outros usuários.\n\nchmod 755 policial.pdf", "C", "No chmod 755, cada dígito soma leitura (4), escrita (2) e execução (1). O 7 dá leitura, escrita e execução ao proprietário; os dois 5 dão leitura e execução ao grupo e aos outros usuários.", ""],
  [82, "", 2, "info", "Computação em nuvem", [25], "A infraestrutura como serviço (IaaS) oferece aos usuários recursos computacionais virtuais como servidores, armazenamento e redes, mas o gerenciamento do sistema operacional fica sob responsabilidade do cliente.", "C", "No IaaS, o provedor entrega máquinas virtuais, armazenamento e redes. Instalar, atualizar e administrar o sistema operacional fica com o cliente.", ""],
  [83, "", 2, "info", "DNS", [25], "O DNS é responsável por garantir a confidencialidade das comunicações entre cliente e servidor por meio de criptografia ponta a ponta embutida no próprio protocolo desde a sua concepção.", "E", "O DNS foi criado sem criptografia: as consultas trafegam abertas. O DNSSEC, acrescentado depois, garante a autenticidade e a integridade das respostas, não o sigilo. O sigilo veio com extensões posteriores, como DNS sobre TLS e DNS sobre HTTPS.", ""],
  [84, "", 2, "info", "DNS", [25], "O DNS utiliza o protocolo UDP para a maioria das consultas, mas pode usar o TCP para transferência de zonas e consultas que excedam 512 bytes.", "C", "O DNS usa a porta 53, em geral pelo UDP. O TCP entra nas transferências de zona entre servidores e quando a resposta passa de 512 bytes.", ""],
  [86, "", 2, "info", "Autenticação multifator", [26], "Em autenticação multifator (MFA), hardwares tokens equivalem a dispositivos físicos que geram códigos de autenticação ou permitem autenticação via porta USB em computadores com esse tipo de interface.", "C", "Tokens de hardware são dispositivos físicos que geram códigos de uso único ou se conectam ao computador, como as chaves de segurança USB. São o fator “algo que você tem”.", ""],
  [87, "", 2, "info", "Ameaças e proteção (sandbox)", [26], "A técnica sandboxing, ao executar programas em um ambiente compartilhado para observar seu comportamento, altera o sistema principal.", "E", "O sandboxing executa o programa num ambiente isolado, e não compartilhado, justamente para observar o comportamento sem alterar o sistema principal.", ""],
  [88, "", 2, "info", "Ameaças e proteção (antivírus)", [26], "Detecção heurística é uma técnica de análise do comportamento e da estrutura do código para a identificação de características típicas de vírus, ainda que a assinatura específica não seja conhecida.", "C", "A detecção heurística analisa o comportamento e a estrutura do código em busca de traços típicos de malware. Assim, identifica ameaças novas, que ainda não têm assinatura conhecida.", ""],
  [89, "", 2, "info", "Banco de dados (ACID)", [27], "Por princípio, a consistência pressupõe que uma transação inconsistente deve levar o banco de dados de um estado inconsistente para o estado consistente.", "E", "Pela consistência (o C do ACID), a transação leva o banco de um estado consistente a outro estado consistente. Ela não parte de um estado inconsistente.", ""],
  [90, "", 2, "info", "Banco de dados (ACID)", [27], "Para a garantia dos princípios de atomicidade em banco de dados, uma transação somente é confirmada e tornada permanente no banco de dados após todas as suas operações serem executadas com sucesso.", "C", "Pela atomicidade, a transação é tudo ou nada: só é confirmada (commit) e gravada de forma permanente se todas as operações derem certo. Se uma falhar, tudo é desfeito (rollback).", ""],
  [92, "", 2, "info", "SQL", [28, 29], "Pelo comando SELECT, entende-se que os valores da coluna valor_venda devem ser menores que zero.", "E", "O registro da tabela catalogo traz a regra de negócio 'valor_venda > 0': os valores da coluna valor_venda devem ser maiores que zero, e não menores.", ""],
  [93, "", 2, "info", "Machine learning", [30], "Em aprendizado de máquina, as técnicas de classificação e regressão são exemplos de aplicações práticas para a solução de problemas.", "C", "Classificação (prever uma categoria) e regressão (prever um valor numérico) são tarefas clássicas do aprendizado de máquina, usadas para resolver problemas práticos.", ""],
  [95, "", 2, "info", "Machine learning", [30], "Em aprendizado de máquina, não há overfitting.", "E", "O overfitting (sobreajuste) existe e é um problema comum: o modelo se ajusta demais aos dados de treino, inclusive ao ruído, e erra em dados novos.", ""],
  [96, "", 2, "info", "APIs", [30], "Uma API deve manter estado entre as requisições visto que, para cada requisição, é necessária a completude oriunda de outra requisição a fim de que a aplicação tenha todas as informações necessárias para processá-la.", "E", "APIs no padrão REST são sem estado (stateless): cada requisição traz todas as informações necessárias para ser processada, sem depender de outra.", ""],
  [97, "", 3, "contab", "Lançamentos (débito e crédito)", [31], "Uma empresa que realiza a compra de um terreno no valor de R$ 120.000 à vista, com recursos bancários, deve lançar esse valor a débito na conta bancos e a crédito na conta terrenos, pois está saindo dinheiro e entrando um bem.", "E", "Está invertido. O terreno que entra aumenta o ativo e vai a débito na conta terrenos; o dinheiro que sai diminui o ativo e vai a crédito na conta bancos.", ""],
  [98, "", 3, "contab", "Plano de contas e livros", [31], "O plano de contas é um dos livros contábeis obrigatórios das empresas, devendo ser registrado e autenticado na junta comercial juntamente com o livro diário e o livro-razão.", "E", "O plano de contas não é livro: é a relação organizada das contas que a entidade usa, e não é registrado na junta comercial. O livro obrigatório autenticado na junta é o Diário (Código Civil, arts. 1.180 e 1.181).", ""],
  [99, "", 3, "contab", "Finalidade da contabilidade", [31], "A principal finalidade do relatório financeiro para fins gerais é atender às necessidades da administração da entidade, fornecendo informações internas detalhadas para o planejamento e controle operacional e priorizando os usuários internos em detrimento dos externos.", "E", "Pela Estrutura Conceitual (CPC 00), o relatório financeiro para fins gerais serve aos investidores, credores por empréstimo e outros credores, existentes e potenciais, que decidem se fornecem recursos à entidade. A administração tem acesso a informações internas e não depende desses relatórios.", ""],
  [100, "", 3, "contab", "Fatos administrativos", [31], "Uma movimentação entre contas do ativo e do passivo é classificada como fato modificativo, uma vez que envolve variação na estrutura patrimonial da entidade e altera diretamente o valor do patrimônio.", "E", "Movimentar contas do ativo e do passivo sem mexer no patrimônio líquido é fato permutativo. Pagar uma dívida com dinheiro do banco, por exemplo, diminui o ativo e o passivo no mesmo valor. Fato modificativo é o que altera o patrimônio líquido, como receitas e despesas.", ""],
  [101, "", 3, "contab", "Patrimônio líquido", [31], "O valor do patrimônio líquido de uma entidade no início de determinado ano resulta da diferença entre o total de bens e direitos da entidade e o montante de suas obrigações.", "C", "Patrimônio líquido = ativo (bens e direitos) – passivo (obrigações). A conta vale em qualquer data, inclusive no início do ano.", ""],
  [102, "", 3, "contab", "Fatos administrativos", [32], "Os fatos administrativos permutativos correspondem à troca entre elementos do ativo ou do passivo que não alteram o patrimônio líquido, tal como ocorre na aquisição de um item para venda com pagamento à vista, que reduz o ativo caixa e aumenta o ativo estoque; entretanto, uma troca que envolva aumento simultâneo do ativo e do passivo não caracteriza fato permutativo, pois altera o patrimônio da empresa.", "E", "Comprar a prazo aumenta o ativo (o bem) e o passivo (a dívida) no mesmo valor, sem alterar o patrimônio líquido. Por isso também é fato permutativo, e a parte final do item está errada.", ""],
  [103, "", 3, "contab", "Regime de competência", [32], "Considere que, em determinado período, uma empresa tenha vendido R$ 125.000 e só recebido R$ 115.000 (o restante receberá no futuro); considere, ainda, que a mesma empresa tenha tido, no mesmo período, despesa de R$ 110.000 e tenha pago R$ 108.000. Com base nesses dados, conclui-se que, pelo regime de competência, a empresa apresentou lucro de R$ 15.000 no período.", "C", "Pelo regime de competência, contam as receitas e despesas do período, recebidas ou pagas ou não: R$ 125.000 – R$ 110.000 = R$ 15.000 de lucro.", ""],
  [104, "", 3, "contab", "Livro diário", [32], "O livro diário deve conter, para cada lançamento, a data do fato, a conta debitada, a conta creditada, o histórico da operação e o valor correspondente, e nele deve-se obedecer à ordem cronológica dos registros.", "C", "O Diário registra as operações em ordem cronológica, e cada lançamento traz a data, a conta debitada, a conta creditada, o histórico e o valor.", ""],
  [105, "", 3, "contab", "Regime de competência", [32], "Pelo regime de competência, as receitas de vendas devem ser contabilizadas somente no momento do recebimento do dinheiro, independentemente da entrega do produto ou serviço.", "E", "Pelo regime de competência, a receita é reconhecida quando é ganha, na entrega do produto ou na prestação do serviço, seja qual for a data do recebimento. Registrar só quando o dinheiro entra é o regime de caixa.", ""],
  [106, "", 3, "contab", "Despesas antecipadas", [32], "O valor pago antecipadamente pelo aluguel de uma sala comercial para uso por período de seis meses deve ser registrado pela empresa locatária como um direito no ativo, na conta despesas antecipadas, e deverá ser apropriado mensalmente como despesa, à medida que o direito de uso da sala for sendo consumido.", "C", "O aluguel pago antes do uso é um direito (despesa antecipada, no ativo). A cada mês de uso, uma parte vira despesa, até a conta zerar no fim dos seis meses.", ""],
  [107, "", 3, "contab", "Balancete (apuração)", [33, 34], "O patrimônio líquido total da entidade, considerado o resultado do exercício, é de R$ 100.000.", "E", "Lucro = receita de R$ 7.000 – despesas de R$ 1.500 e R$ 2.000 = R$ 3.500. Patrimônio líquido = capital de R$ 100.000 + R$ 3.500 = R$ 103.500. Conferindo: ativo de R$ 109.200 – passivo de R$ 5.700 = R$ 103.500.", ""],
  [108, "", 3, "contab", "Balancete (apuração)", [33, 34], "O passivo circulante resulta no valor de R$ 5.700.", "C", "A única obrigação da lista é contas a pagar, de R$ 5.700, que fica no passivo circulante.", ""],
  [109, "", 3, "contab", "Balancete (apuração)", [33, 34], "O ativo soma R$ 109.200.", "C", "Ativo = bancos R$ 95.000 + materiais de consumo R$ 4.000 + máquinas R$ 9.000 + despesa antecipada R$ 1.200 = R$ 109.200.", ""],
  [110, "", 3, "contab", "Balancete (apuração)", [33, 34], "O lucro apurado no exercício é de R$ 3.500.", "C", "Lucro = receita de serviços de R$ 7.000 – despesas com taxas de R$ 1.500 – pró-labore de R$ 2.000 = R$ 3.500.", ""],
  [113, "", 3, "contab", "Demonstração do resultado", [35], "Na demonstração de resultados do exercício, a receita líquida corresponde à receita bruta menos as deduções, tais como devoluções de venda, impostos sobre vendas e descontos comerciais.", "C", "Receita líquida = receita bruta – deduções, como devoluções e abatimentos, impostos sobre vendas e descontos comerciais.", ""],
  [114, "", 3, "contab", "Depreciação", [36], "Um ativo temporariamente retirado de uso deve continuar sendo depreciado, exceto se já estiver totalmente depreciado ou se o método de depreciação adotado estiver diretamente vinculado ao seu uso.", "C", "Pelo CPC 27, a depreciação não para quando o ativo fica ocioso ou é retirado de uso, a menos que já esteja totalmente depreciado. Se o método for pelo uso (como unidades produzidas), a despesa pode ficar zero enquanto não houver produção.", ""],
  [115, "", 3, "contab", "Provisões e contingências", [36], "A provisão para contingência deve ser reconhecida no passivo sempre que a perda for considerada possível, independentemente do trânsito em julgado da ação judicial que a motivou.", "E", "Pelo CPC 25, a provisão só é reconhecida quando a saída de recursos é provável e o valor pode ser estimado com confiança. Se a perda é apenas possível, há passivo contingente: não se reconhece, só se divulga em nota explicativa.", ""],
  [116, "", 3, "contab", "Provisão de férias", [36], "A provisão para férias representa um passivo para a empresa e deve ser reconhecida como despesa por ocasião do gozo de férias pelo empregado.", "E", "Pelo regime de competência, a despesa com férias é reconhecida mês a mês, à medida que o empregado adquire o direito, e não quando ele goza as férias.", ""],
  [118, "", 3, "contab", "CPC 00 (características qualitativas)", [37], "A relevância e a compreensibilidade são as características fundamentais da informação contábil.", "E", "Pelo CPC 00 (R2), as características qualitativas fundamentais são a relevância e a representação fidedigna. A compreensibilidade é uma característica de melhoria, ao lado da comparabilidade, da verificabilidade e da tempestividade.", ""],
  [119, "", 3, "contab", "CPC 00 (características qualitativas)", [37], "A relevância da informação contábil está associada à sua capacidade de influenciar as decisões econômicas de seus usuários.", "C", "Informação relevante é a capaz de fazer diferença nas decisões dos usuários, por ter valor preditivo, valor confirmatório ou ambos (CPC 00 (R2)).", ""],
  [120, "", 3, "contab", "CPC 00 (bases de mensuração)", [37], "O custo corrente de um ativo corresponde ao valor presente dos fluxos de caixa futuros que a entidade espera obter a partir do uso contínuo do ativo.", "E", "Pelo CPC 00 (R2), o valor presente dos fluxos de caixa esperados do uso do ativo é o valor em uso. O custo corrente é o custo de um ativo equivalente na data de mensuração: o que se pagaria nessa data mais os custos de transação.", ""],
];
